		function mazeTitleLegalCharacters(field, e)
		{
			if (!e) var e = window.event
			if (e.keyCode) code = e.keyCode;
			else if (e.which) code = e.which;
			var character = String.fromCharCode(code);

			var restriction = /[0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ !\-\.\?,]/g;

			// if they pressed esc... remove focus from field...
			if (code==27) { this.blur(); return false; }

			// ignore if they are pressing other keys
			// strange because code: 39 is the down key AND ' key...
			// and DEL also equals .
			if (!e.ctrlKey && code!=9 && code!=8 && (code!=36 || (code==36 && character=="$")) && (code!=37 || (code==37 && character=="%")) && (code!=38 || (code==38 && character=="&")) && (code!=39 || (code==39 && character=="'")) && (code!=40 || (code==40 && character=="("))) {
				if (character.match(restriction)) {
					return true;
				} else {
					return false;
				}
			}
			return true;
		}

