		function closeForm(user, position)
		{
			//Verify new settings
			var name = document.getElementById('formname-'+user);
			var password1 = document.getElementById('formpassword1-'+user);
			var password2 = document.getElementById('formpassword2-'+user);
			var email = document.getElementById('formemail-'+user);
			var birthyear = document.getElementById('formbirthyear-'+user);
			var country = document.getElementById('formcountry-'+user);
			var subscribe = document.getElementById('formsubscribe-'+user);

			var nameToSubmit;
			var passwordToSubmit1;
			var passwordToSubmit2;
			var emailToSubmit;
			var birthyearToSubmit;
			var countryToSubmit;
			var subscribeToSubmit;

			var legalCharacters="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-";
			var illegalCharacters=" \t\n\r\x0B\0'\"";
	
			//First check if name is legal
			if (!formCheckEmpty(name, "name"))
			{
				if (name.value.length > 30)
				{
					formDisplayError('formname', user, 'Name is too long!<br>');
					formClearErrors(new Array('formpassword1', 'formpassword2', 'formemail'), user);
					return false;
				}

				nameToSubmit = name.value;
			}
			else
				nameToSubmit = "";

			//Also check if password is legal
			var passwordIllegal = false;
			for (var i=0; i < password1.value.length; i++)
			{
				if (illegalCharacters.indexOf(password1.value.charAt(i)) >= 0)
				{
					passwordIllegal = true;
				}
			}

			if (!formCheckEmpty(password1, "password"))
			{
				if (passwordIllegal)
				{
					formDisplayError('formpassword1', user, 'Illegal password!');
					formClearErrors(new Array('formname', 'formpassword2', 'formemail'), user);
					return false;
				}
				else if (formCheckEmpty(password2, "password"))
				{
					formDisplayError('formpassword2', user, 'Must repeat password!');
					formClearErrors(new Array('formname', 'formpassword1', 'formemail'), user);
					return false;
				}
				else if (password1.value != password2.value)
				{
					formDisplayError('formpassword1', user, 'Passwords do not match!');
					formDisplayError('formpassword2', user, 'Passwords do not match!');
					formClearErrors(new Array('formname', 'formemail'), user);
					return false;
				}
				else if (password1.value.length > 32)
				{
					formDisplayError('formpassword1', user, 'Password too long!');
					formClearErrors(new Array('formname', 'formpassword2', 'formemail'), user);
					return false;
				}
				
				passwordToSubmit1 = password1.value;
				passwordToSubmit2 = password2.value;
			}
			else
			{
				passwordToSubmit1 = "";
				passwordToSubmit2 = "";
			}

			if (!formCheckEmpty(email, "email"))
			{
				if (email.value.length > 128)
				{
					formDisplayError('formemail', user, 'Email address too long!<br>&nbsp;<br>&nbsp;');
					formClearErrors(new Array('formpassword1', 'formpassword2', 'formname'), user);
					return false;
				}
				
				if (email.value.indexOf("@") == -1)
				{
					formDisplayError('formemail', user, 'Illegal email!<br>&nbsp;<br>&nbsp;');
					formClearErrors(new Array('formpassword1', 'formpassword2', 'formname'), user);
					return false;
				}
			
				emailToSubmit = email.value;
			}
            else
            {
				formDisplayError('formemail', user, 'Must supply an email!<br>&nbsp;<br>&nbsp;');
				formClearErrors(new Array('formpassword1', 'formpassword2', 'formname'), user);
                return false;
            }
            
            if (!emailChecked) 
            {
				formDisplayError('formemail', user, 'Email is being checked!<br>&nbsp;<br>&nbsp;');
				formClearErrors(new Array('formpassword1', 'formpassword2', 'formname'), user);
                return false;
            }
            
            if (!emailUnused)
            {
				formDisplayError('formemail', user, 'Email is already in use!<br>&nbsp;<br>&nbsp;');
				formClearErrors(new Array('formpassword1', 'formpassword2', 'formname'), user);
                return false;
            }
				
			
			formClearErrors(new Array('formname', 'formpassword1', 'formpassword2', 'formemail'), user);

			countryToSubmit = country.value;
			birthyearToSubmit = birthyear.value;
			if (subscribe.checked)
				subscribeToSubmit = "1";
			else
				subscribeToSubmit = "0";
		
			//Save new settings
			x_updateFormData(user, nameToSubmit, passwordToSubmit1, passwordToSubmit2, emailToSubmit, birthyearToSubmit, countryToSubmit, subscribeToSubmit, updateFormData_cb);
			
			formIconToUpdate = document.getElementById("userpanelForm-"+user);
			
			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelContent-" + user+"'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(99); tempFX = new Fx.Style(document.getElementById('userpanelswrapper'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(214);", 700);

			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'width', {onComplete: function() {document.getElementById('userSettingsTank-"+user+"').style.visibility='visible';}, duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(224); tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'left', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start("+position+");", 1200);
		
			enableUserPanelIcons(user, 1700);

			setTimeout("document.getElementById('userSettingsTankFlash-"+user+"').SetVariable('fadeOut', 'false');", 2300); // 1700 + 15frames/25fps * 1000 = 4300

			tempFX = new Fx.Style(document.getElementById('userpanelFormInput-'+user), 'opacity', {onComplete: function() {document.getElementById('userpanelFormInput-'+user).style.display="none"; document.getElementById('userpanelFormInput-'+user).style.visibility="hidden";}, duration: 200, transition: Fx.Transitions.linear});
			tempFX.start(0);

			tempFX = new Fx.Style(document.getElementById('userpanelAcceptForm-'+user), 'opacity', {onComplete: function() {document.getElementById('userpanelAcceptForm-'+user).style.display="none"; document.getElementById('userpanelAcceptForm-'+user).style.visibility="hidden";}, duration: 200, transition: Fx.Transitions.linear});
			tempFX.start(0);
			
			// Update onkeyup function to reflect new submitted email address
			var status = document.getElementById('formemailstatusmessage-'+user).innerHTML != "A verification email will be sent to your new address" && document.getElementById('formemailstatusmessage-'+user).innerHTML == "Verified";
			formEmailStatus(user, 'formemailstatusmessage-'+user, 'formemail-'+user, emailToSubmit, status);
			document.getElementById('formemail-'+user).onkeyup = function() { formEmailStatus(user, 'formemailstatusmessage-'+user, 'formemail-'+user, emailToSubmit, status); };
			
			return true;

		}

		function formEmailStatus(user, messageElementId, elementId, oldValue, oldStatus)
		{
			if (formCheckEmpty(document.getElementById(elementId), "email"))
			{
				var opacityFX = new Fx.Style(document.getElementById(messageElementId), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
				opacityFX.start(0);
				setTimeout('document.getElementById("'+messageElementId+'").innerHTML = ""; var opacityFX = new Fx.Style(document.getElementById("'+messageElementId+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);

    			formClearErrors(new Array('formemail'), user);
				return;
			}
		
			if (document.getElementById(elementId).value != oldValue)
			{
				if (document.getElementById(messageElementId).innerHTML != "A verification email will be sent to your new address")
				{
					var opacityFX = new Fx.Style(document.getElementById(messageElementId), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
					opacityFX.start(0);
					setTimeout('document.getElementById("'+messageElementId+'").innerHTML = "A verification email will be sent to your new address"; var opacityFX = new Fx.Style(document.getElementById("'+messageElementId+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
				}
                
                emailChecked = false;
                userWhoseEmailIsBeingChecked = user;
                x_formCheckEmail(user, document.getElementById(elementId).value, formCheckEmail_cb);
			}
			else
			{
				if (document.getElementById(messageElementId).innerHTML == "A verification email will be sent to your new address")
				{
					var opacityFX = new Fx.Style(document.getElementById(messageElementId), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
					opacityFX.start(0);
					setTimeout('document.getElementById("'+messageElementId+'").innerHTML = "'+(oldStatus == "1"?'Verified':'Not verified')+'"; var opacityFX = new Fx.Style(document.getElementById("'+messageElementId+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
    				formClearErrors(new Array('formemail'), user);
				}
			}
		}
        
        function formCheckEmail_cb(response)
        {
            emailChecked = true;
            if (response == "OK") 
            {
                emailUnused = true;
				formClearErrors(new Array('formname', 'formpassword1', 'formpassword2', 'formemail'), userWhoseEmailIsBeingChecked);
            } 
            else
            {
                emailUnused = false;
				formDisplayError('formemail', userWhoseEmailIsBeingChecked, response);
				formClearErrors(new Array('formname', 'formpassword1', 'formpassword2'), userWhoseEmailIsBeingChecked);
            }
        }

		function formCheckEmpty(element, emptyString)
		{
			return (element.value == "" || (element.value == emptyString && !(element.style.color == "#000000" || element.style.color == "rgb(0, 0, 0)")));
		}

		function formCheckKey(event, moveTo)
		{
			if (event.which == 13 || event.keyCode == 13)
			{
				document.getElementById(moveTo).focus();
				return false;
			}
			return true;
		}

		function formDisplayError(elementId, user, error)
		{
			document.getElementById(elementId+'text-'+user).className = "text medium red";
			
			var mes = document.getElementById(elementId+'message-'+user).innerHTML.toLowerCase();
			var idx = mes.indexOf('<');
			if ((idx < 0 && mes != error.toLowerCase()) || (idx >= 0 && mes.substring(0,idx) != error.substring(0, error.indexOf('<')).toLowerCase()))
			{
				var opacityFX = new Fx.Style(document.getElementById(elementId+'message-'+user), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
				opacityFX.start(0);
				setTimeout('document.getElementById("'+elementId+'message-'+user+'").innerHTML = "'+error+'"; document.getElementById("'+elementId+'message-'+user+'").className="text tiny red"; var opacityFX = new Fx.Style(document.getElementById("'+elementId+'message-'+user+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
			}
		}

		function formClearErrors(elementIds, user)
		{
			for (var i = 0; i < elementIds.length; i++)
			{
				if (document.getElementById(elementIds[i]+'text-'+user).className != "text medium")
				{
					document.getElementById(elementIds[i]+'text-'+user).className = "text medium";
					var opacityFX = new Fx.Style(document.getElementById(elementIds[i]+'message-'+user), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
					opacityFX.start(0);
					setTimeout('document.getElementById("'+elementIds[i]+'message-'+user+'").innerHTML = "'+originalFormMessages[elementIds[i]]+'"; document.getElementById("'+elementIds[i]+'message-'+user+'").className="text tiny gray"; var opacityFX = new Fx.Style(document.getElementById("'+elementIds[i]+'message-'+user+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
				}
			}
		}
		
		function updateFormData_cb(r)
		{
			if (r != "")
				formIconToUpdate.src = r;
		}		

		function openStats(user)
		{
			document.getElementById('userSettingsTankFlash-'+user).SetVariable("fadeOut", "true");

			setTimeout("document.getElementById('userSettingsTank-"+user+"').style.visibility='hidden'; var tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'width', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(692); tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'left', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(0);", 700);
			
			disableUserPanelIcons(user);

			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelContent-" + user + "'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(605);", 1200);
			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelswrapper'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(720);", 1200);

			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelStatsPage-"+user+"'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); tempFX.set(0); document.getElementById('userpanelStatsPage-"+user+"').style.display='block'; document.getElementById('userpanelStatsPage-"+user+"').style.visibility='visible'; tempFX.start(1);", 1700);

			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelAcceptStats-"+user+"'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); tempFX.set(0); document.getElementById('userpanelAcceptStats-"+user+"').style.display='block'; document.getElementById('userpanelAcceptStats-"+user+"').style.visibility='visible'; tempFX.start(1);", 1700);
		}
		
		function closeStats(user, position)
		{
			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelContent-" + user+"'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(99); tempFX = new Fx.Style(document.getElementById('userpanelswrapper'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(214);", 700);

			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'width', {onComplete: function() {document.getElementById('userSettingsTank-"+user+"').style.visibility='visible';}, duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start(224); tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'left', {duration: 500, transition: Fx.Transitions.Quad.easeInOut}); tempFX.start("+position+");", 1200);
		
			enableUserPanelIcons(user, 1700);

			setTimeout("document.getElementById('userSettingsTankFlash-"+user+"').SetVariable('fadeOut', 'false');", 2300); // 1700 + 15frames/25fps * 1000 = 4300

			tempFX = new Fx.Style(document.getElementById('userpanelStatsPage-'+user), 'opacity', {onComplete: function() {document.getElementById('userpanelStatsPage-'+user).style.display="none"; document.getElementById('userpanelStatsPage-'+user).style.visibility="hidden";}, duration: 200, transition: Fx.Transitions.linear});
			tempFX.start(0);

			tempFX = new Fx.Style(document.getElementById('userpanelAcceptStats-'+user), 'opacity', {onComplete: function() {document.getElementById('userpanelAcceptStats-'+user).style.display="none"; document.getElementById('userpanelAcceptStats-'+user).style.visibility="hidden";}, duration: 200, transition: Fx.Transitions.linear});
			tempFX.start(0);

		}


		
		function hideUserPanel(user)
		{
			document.getElementById('userSettingsTankFlash-'+user).SetVariable("fadeOut", "true");

			//Hide buttons explicitly as they seem to lose dependence on userpanels visibility when they are faded out/in by dis/enableUserPanelIcons
			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'opacity', {onComplete: function() { document.getElementById('userpanel-"+user+"').style.visibility = 'hidden'; document.getElementById('userpanelPaint-"+user+"').style.visibility = 'hidden'; document.getElementById('userpanelMaze-"+user+"').style.visibility = 'hidden'; if (document.getElementById('userpanelSherifStar-"+user+"') != null) document.getElementById('userpanelSherifStar-"+user+"').style.visibility = 'hidden'; document.getElementById('userpanelForm-"+user+"').style.visibility = 'hidden'; document.getElementById('userpanelStats-"+user+"').style.visibility = 'hidden';}, duration: 200, transition: Fx.Transitions.linear}); tempFX.start(0);", 500);
			
			setTimeout('document.getElementById("userSettingsTank-'+user+'").style.visibility = "hidden"', 700);
		}
		
		function showUserPanel(user, delay)
		{
			//Show buttons explicitly as they seem to lose dependence on userpanels visibility when they are faded out/in by dis/enableUserPanelIcons
			setTimeout("document.getElementById('userpanel-"+user+"').style.visibility = 'visible'; document.getElementById('userSettingsTank-"+user+"').style.visibility = 'visible'; document.getElementById('userpanelPaint-"+user+"').style.visibility = 'visible'; document.getElementById('userpanelMaze-"+user+"').style.visibility = 'visible'; if (document.getElementById('userpanelSherifStar-"+user+"') != null) document.getElementById('userpanelSherifStar-"+user+"').style.visibility = 'visible'; document.getElementById('userpanelForm-"+user+"').style.visibility = 'visible'; document.getElementById('userpanelStats-"+user+"').style.visibility = 'visible'; tempFX = new Fx.Style(document.getElementById('userpanel-"+user+"'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); tempFX.start(1);", delay);
			setTimeout("document.getElementById('userSettingsTankFlash-"+user+"').SetVariable('fadeOut', 'false'); document.getElementById('userSettingsTankFlash-"+user+"').SetVariable('initDelay','15');", delay+1); //This needs to happen AFTER the display is set back to 'block', otherwise SetVariable evaluates to undefined. It cannot even happen in the same setTimeout..
		}

		function doRemoveUserPanels()
		{
			//Handle correct fade out of flashes before the rest
			var element = document.getElementById('loginAllUserInfo');
			var currentElement = element.firstChild;
			while (currentElement != null)
			{
				if (document.getElementById('userSettingsTankFlash-'+currentElement.innerHTML) != null) //&& document.getElementById('userSettingsTankFlash-'+currentElement.innerHTML).SetVariable != null)
					document.getElementById('userSettingsTankFlash-'+currentElement.innerHTML).SetVariable("fadeOut", "true");
				currentElement = currentElement.nextSibling;
			}
			
			setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelscontent'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); tempFX.start(0); tempFX = new Fx.Style(document.getElementById('userpanelsheader'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); tempFX.start(0);", 500);
		}
		
		function getAllUserInfo_cb(r)
		{
			var element = document.getElementById('loginAllUserInfo');
			element.innerHTML = r;
			x_updateUserPanels(updateUserPanels_cb);
		}
		
		function updateUserPanels_cb(r)
		{
			var newElement = document.createElement('div');
			newElement.innerHTML = r;
			var currentElement = newElement.firstChild;

			document.getElementById('userpanelsheader').style.display = "none";
			document.getElementById('userpanelsheader').innerHTML = currentElement.innerHTML;

			currentElement = currentElement.nextSibling;
			var oldHTML = document.getElementById('userpanelscontent').innerHTML;
			document.getElementById('userpanelscontent').style.display = "none";
			document.getElementById('userpanelscontent').innerHTML = currentElement.innerHTML;

			if (currentElement.innerHTML != "")
			{
				//Show user panels
//				if (oldHTML == "")
				{
					tempFX = new Fx.Style(document.getElementById('userpanelswrapper'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut});
					tempFX.start(214);
				}

				setTimeout("var tempFX = new Fx.Style(document.getElementById('userpanelscontent'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); document.getElementById('userpanelscontent').style.display = 'block'; tempFX.start(1); tempFX = new Fx.Style(document.getElementById('userpanelsheader'), 'opacity', {duration: 200, transition: Fx.Transitions.linear}); document.getElementById('userpanelsheader').style.display = 'block'; tempFX.start(1);", (oldHTML == "" ? 500 : 0));
			}
			else
			{
				//Hide user panels
				tempFX = new Fx.Style(document.getElementById('userpanelswrapper'), 'height', {duration: 500, transition: Fx.Transitions.Quad.easeInOut});
				tempFX.start(0);
			}

			//Insert flashes
			while (currentElement.nextSibling != null)
			{
				currentElement = currentElement.nextSibling;
				var sy = new SWFObject("includes/signUpTankDesign18StandardColours.swf", "userSettingsTankFlash-"+currentElement.getAttribute('name'), "600", "250", "8", "#ffffff");
				sy.addParam("allowScriptAccess", "sameDomain");
				sy.addParam("menu", "false");
				sy.addParam("quality", "best");
				sy.addParam("wmode", "transparent");
//				alert(currentElement.innerHTML);
				sy.addParam("FlashVars", "initCode="+currentElement.innerHTML+"&initDelay=15");
				sy.write("userSettingsTank-"+currentElement.getAttribute('name'));
			}
		}

		// -->
</script><div id ="signupresult" class="text normal" style="text-align: center;">
