<script type="text/javascript">
	<!--
		var originalMessages = new Array();
		originalMessages["signupusername"] = "Something awesome!";
		originalMessages["signuppassword1"] = "Something secret...";
		originalMessages["signuppassword2"] = "&nbsp;";
		originalMessages["signupemail"] = "Needed to recover your<br/>password and other<br/>important stuff!";
		originalMessages["signupcolor"] = "&nbsp;";
	
		function doSignup()
		{
			//Do basic checks
			var username = document.getElementById('signupusername');
			var password1 = document.getElementById('signuppassword1');
			var password2 = document.getElementById('signuppassword2');
			var email = document.getElementById('signupemail');
			var tankname = document.getElementById('signuptankname');
			var trackscolor = document.getElementById('signuptrackscolor');
			var turretcolor = document.getElementById('signupturretcolor');

			var legalCharacters="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-";
			var illegalCharacters=" \t\n\r\x0B\0'\"";
	
			//First check if username is legal
			var charCount = 0;
			for (var i=0; i < username.value.length; i++)
			{
				if (legalCharacters.indexOf(username.value.charAt(i)) >= 0)
				{
					charCount++;
				}
			}

			//Also check if password is legal
			var passwordIllegal = false;
			for (var i=0; i < password1.value.length; i++)
			{
				if (illegalCharacters.indexOf(password1.value.charAt(i)) >= 0)
				{
					passwordIllegal = true;
				}
			}

			if (signupCheckEmpty(username, "tank name"))
			{
				signupDisplayError('signupusername', 'Must supply a username!');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (charCount != username.value.length)
			{
				signupDisplayError('signupusername', 'Illegal username!');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (username.value.length > 32)
			{
				signupDisplayError('signupusername', 'Username too long!');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (signupCheckEmpty(password1, "password"))
			{
				signupDisplayError('signuppassword1', 'Must supply a password!');
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (passwordIllegal)
			{
				signupDisplayError('signuppassword1', 'Illegal password!');
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (signupCheckEmpty(password2, "password"))
			{
				signupDisplayError('signuppassword2', 'Must repeat password!');
				signupClearErrors(new Array('signupusername', 'signuppassword1', 'signupemail', 'signupcolor'));
			}
			else if (password1.value != password2.value)
			{
				signupDisplayError('signuppassword1', 'Passwords do not match!');
				signupDisplayError('signuppassword2', 'Passwords do not match!');
				signupClearErrors(new Array('signupusername', 'signupemail', 'signupcolor'));
			}
			else if (password1.value.length > 32)
			{
				signupDisplayError('signuppassword1', 'Password too long!');
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (signupCheckEmpty(email, "email"))
			{
				signupDisplayError('signupemail', 'Must supply an email!<br>&nbsp;<br>&nbsp;');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupcolor'));
			}
			else if (email.value.length > 128)
			{
				signupDisplayError('signupemail', 'Email address too long!<br>&nbsp;<br>&nbsp;');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupcolor'));
			}
			else if (trackscolor.value == '0xffffff' || turretcolor.value == '0xffffff')
			{
				signupDisplayError('signupcolor', 'Paint both turret and base!');
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupemail'));
			}
			else
			{
				x_signup(username.value, password1.value, password2.value, email.value, document.getElementById('signuptrackscolor').value, document.getElementById('signupturretcolor').value, doSignup_cb);
			}
		}
		
		function doSignup_cb(r)
		{
			if (r == "Username too long!")
			{
				signupDisplayError('signupusername', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Illegal username!")
			{
				signupDisplayError('signupusername', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Illegal password!")
			{
				signupDisplayError('signuppassword1', r);
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Must differ from username!")
			{
				signupDisplayError('signuppassword1', r);
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Password too short!")
			{
				signupDisplayError('signuppassword1', r);
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Password too long!")
			{
				signupDisplayError('signuppassword1', r);
				signupClearErrors(new Array('signupusername', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Passwords do not match!")
			{
				signupDisplayError('signuppassword1', r);
				signupDisplayError('signuppassword2', r);
				signupClearErrors(new Array('signupusername', 'signupemail', 'signupcolor'));
			}
			else if(r == "Email address too long!<br>&nbsp;<br>&nbsp;")
			{
				signupDisplayError('signupemail', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupcolor'));
			}
			else if(r == "Illegal email!<br>&nbsp;<br>&nbsp;")
			{
				signupDisplayError('signupemail', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupcolor'));
			}
			else if(r == "Try again in a moment!")
			{
				signupDisplayError('signupusername', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if (r == "Username not allowed!")
            {
                signupDisplayError('signupusername', r);
                signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
            }
			else if(r == "Username already taken!")
			{
				signupDisplayError('signupusername', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupcolor'));
			}
			else if(r == "Email already in use!<br>&nbsp;<br>&nbsp;")
			{
				signupDisplayError('signupemail', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupusername', 'signupcolor'));
			}
			else if (r == "Paint both turret and base!")
			{
				signupDisplayError('signupcolor', r);
				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupusername'));
			}
			else
			{
				//Clear form and congratulate!
				document.getElementById("signupusername").value = "tank name";
				document.getElementById("signupusername").style.color = '#666666';
				document.getElementById("signuppassword1").value = "password";
				document.getElementById("signuppassword1").style.color = '#666666';
				document.getElementById("signuppassword2").value = "password";
				document.getElementById("signuppassword2").style.color = '#666666';
				document.getElementById("signupemail").value = "email";
				document.getElementById("signupemail").style.color = '#666666';
				document.getElementById("signupturretcolor").value = '0xffffff';
				document.getElementById("signuptrackscolor").value = '0xffffff';

				signupClearErrors(new Array('signuppassword1', 'signuppassword2', 'signupemail', 'signupusername', 'signupcolor'));
				document.getElementById("signupbutton").disabled = false;

				document.getElementById("signupform").style.display = "none";

				document.getElementById("signupresult").style.display = "block";
				document.getElementById("signupresult").innerHTML = r;
				var c = new SWFObject("includes/loggedInTank06.swf", "signedUpTank", "216", "80", "8", "#ffffff");
				c.addParam("allowScriptAccess", "sameDomain");
				c.addParam("wmode", "transparent");
				c.addParam("menu", "false");
				c.addParam("FlashVars", "initCode="+document.getElementById("signedupinitcode").innerHTML);
				c.write("signedUpTank");
				
				//Also show arrow if first or second login
				//And add highlight to login box
				if (numUsers < 2)
				{
					document.getElementById('signuplogintogetstarted').style.display = "block";
					document.getElementById('login').className = "box important";
				}
			}
		}
		
		function signupCheckEmpty(element, emptyString)
		{
			return (element.value == "" || (element.value == emptyString && !(element.style.color == "#000000" || element.style.color == "rgb(0, 0, 0)")));
		}
		
		function signupCheckKey(event, moveTo)
		{
			if (event.which == 13 || event.keyCode == 13)
			{
				if (moveTo == undefined)
				{
					if (document.getElementById('signupbutton').disabled)
						return false;
					document.getElementById('signupbutton').disabled = true;
					doSignup();
				}
				else
					document.getElementById(moveTo).focus();
				return false;
			}
			return true;
		}
		
		function signupDisplayError(elementId, error)
		{
			document.getElementById(elementId+'text').className = "text medium red";
			
			var mes = document.getElementById(elementId+'message').innerHTML.toLowerCase();
			var idx = mes.indexOf('<');
			if ((idx < 0 && mes != error.toLowerCase()) || (idx >= 0 && mes.substring(0,idx) != error.substring(0, error.indexOf('<')).toLowerCase()))
			{
				var opacityFX = new Fx.Style(document.getElementById(elementId+'message'), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
				opacityFX.start(0);
				setTimeout('document.getElementById("'+elementId+'message").innerHTML = "'+error+'"; document.getElementById("'+elementId+'message").className="text tiny red"; var opacityFX = new Fx.Style(document.getElementById("'+elementId+'message"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
			}
			setTimeout('document.getElementById("signupbutton").disabled = false;', 1000);
//			setTimeout('var opacityFX = new Fx.Style(document.getElementById("'+elementId+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(0);', 1700);
//			setTimeout('document.getElementById("'+elementId+'").innerHTML = "'+oldMessage+'"; document.getElementById("'+elementId+'").className="text tiny gray"; var opacityFX = new Fx.Style(document.getElementById("'+elementId+'"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1); document.getElementById("signupbutton").disabled = false;', 1900);
			
		}
		
		function signupClearErrors(elementIds)
		{
			for (var i = 0; i < elementIds.length; i++)
			{
				if (document.getElementById(elementIds[i]+'text').className != "text medium")
				{
					document.getElementById(elementIds[i]+'text').className = "text medium";
					var opacityFX = new Fx.Style(document.getElementById(elementIds[i]+'message'), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
					opacityFX.start(0);
					setTimeout('document.getElementById("'+elementIds[i]+'message").innerHTML = "'+originalMessages[elementIds[i]]+'"; document.getElementById("'+elementIds[i]+'message").className="text tiny gray"; var opacityFX = new Fx.Style(document.getElementById("'+elementIds[i]+'message"), "opacity", {duration: 200, transition: Fx.Transitions.linear}); opacityFX.start(1);', 200);
				}
			}
		}
		
		// Checks a string for a list of characters
		function signUpCountContain(password, check)
		{ 
		    // Declare variables
		    var nCount = 0;

		    for (i = 0; i < password.length; i++) 
		        if (check.indexOf(password.charAt(i)) > -1) 
	                nCount++;

		    return nCount; 
		} 

		function signUpCheckPassword(password)
		{
    		// Reset combination count
    		var nScore = 0;

    		// Password length
    		// -- Less than 6 characters
    		if (password.length < 6)
    		{
    			nScore += 0;
    		}
		    else if (password.length >= 6 && password.length < 8)
		    {
    		    nScore += 10;
    		}
		    else if (password.length >= 8)
    		{
    		    nScore += 25;
    		}

		    // Letters
		    var nUpperCount = signUpCountContain(password, "ABCDEFGHIJKLMNOPQRSTUVWXYZ");
		    var nLowerCount = signUpCountContain(password, "abcdefghijklmnopqrstuvwxyz");
		    var nLowerUpperCount = nUpperCount + nLowerCount;
		    // -- Letters are all lower case
		    if (nUpperCount == 0 && nLowerCount != 0) 
		        nScore += 10; 
		    // -- Letters are upper case and lower case
		    else if (nUpperCount != 0 && nLowerCount != 0) 
		        nScore += 20; 

		    // Numbers
		    var nNumberCount = signUpCountContain(password, "0123456789");
		    // -- 1 number
		    if (nNumberCount == 1)
		        nScore += 10;
		    // -- 2 or more numbers
		    if (nNumberCount >= 2)
		        nScore += 20;

		    // Characters
		    var nCharacterCount = signUpCountContain(password, "!@#$%^&*?_~");
		    // -- 1 character
		    if (nCharacterCount == 1)
		        nScore += 10;
		    // -- More than 1 character
		    if (nCharacterCount > 1)
		        nScore += 25;

		    // Bonus
		    // -- Letters and numbers
		    if (nNumberCount != 0 && nLowerUpperCount != 0)
		        nScore += 2;
		    // -- Letters, numbers, and characters
		    if (nNumberCount != 0 && nLowerUpperCount != 0 && nCharacterCount != 0)
		        nScore += 3;

		    // -- Mixed case letters, numbers, and characters
		    if (nNumberCount != 0 && nUpperCount != 0 && nLowerCount != 0 && nCharacterCount != 0)
		        nScore += 5;

			// Update message
			var color = "";
			if (nScore >= 80)
				color = "#00d000";
		    // -- Strong
		    else if (nScore >= 60)
		        color = "#00a000";
		    // -- Average
		    else if (nScore >= 40)
		        color = "#e3cb00";
		    // -- Weak
		    else if (nScore >= 20)
		        color = "#ff8080";
		    // -- Very Weak
		    else
		        color = "#ff0000";

			if (signupCheckEmpty(document.getElementById('signuppassword1'), "password"))
			{
				var widthFX = new Fx.Style(document.getElementById("passwordstrength"), "width", {duration: 200, transition: Fx.Transitions.linear}); 
				widthFX.start(nScore);
				var colorFX = new Fx.Style(document.getElementById("passwordstrength"), "backgroundColor", {duration: 200, transition: Fx.Transitions.linear}); 
				colorFX.start("#ffffff");
			}
			else
			{
				var widthFX = new Fx.Style(document.getElementById("passwordstrength"), "width", {duration: 200, transition: Fx.Transitions.linear}); 
				widthFX.start(nScore);
				var colorFX = new Fx.Style(document.getElementById("passwordstrength"), "backgroundColor", {duration: 200, transition: Fx.Transitions.linear}); 
				colorFX.start(color);
			}
		}
		
		
	//-->
