			var curleft = curtop = 0;
			var curright = curbottom = 0;
			var obj = document.getElementById('trail').parentNode;
			if (obj.offsetParent) {
				curleft = obj.offsetLeft
				curtop = obj.offsetTop
				while (obj = obj.offsetParent) {
					curleft += obj.offsetLeft
					curtop += obj.offsetTop
				}
			}

