		function doVote_cb(r)
		{
			var newElement = document.createElement('div');
			newElement.innerHTML = r;
			var oldElement = document.getElementById('poll-'+latestPollId+'-options');
			var oldHeight = document.getElementById('poll-'+latestPollId+'-content').clientHeight;
			var oldTableHeight = document.getElementById('poll-'+latestPollId+'-options').clientHeight;
			var opacityFX = new Fx.Style(newElement.firstChild, "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
			opacityFX.set(0);
			newElement.firstChild.style.position = "absolute";
			oldElement.parentNode.replaceChild(newElement.firstChild, oldElement);
			document.getElementById('poll-'+latestPollId+'-content').style.height = (oldHeight-6)+"px";
			var newTableHeight = document.getElementById('poll-'+latestPollId+'-results').clientHeight;
			document.getElementById('poll-'+latestPollId+'-question').innerHTML = "Your vote was registered";
			document.getElementById('poll-'+latestPollId+'-results').style.display = "none";
			var heightFX = new Fx.Style(document.getElementById('poll-'+latestPollId+'-content'), "height", {onComplete: finishedVoteHeightAnimation, duration: 1500, transition: Fx.Transitions.Bounce.easeOut});
			heightFX.start(oldHeight+(newTableHeight-oldTableHeight));
			document.getElementById('poll-'+latestPollId+'-results').style.position = "relative";

		}

		function finishedVoteHeightAnimation()
		{
			document.getElementById('poll-'+latestPollId+'-results').style.display = "";
			var opacityFX = new Fx.Style(document.getElementById('poll-'+latestPollId+'-results'), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
			opacityFX.start(1);
			opacityFX = new Fx.Style(document.getElementById('poll-'+latestPollId+'-question'), "opacity", {duration: 200, transition: Fx.Transitions.linear}); 
			opacityFX.start(1);
		}
	//-->
</script><a name="05-03-2018" id="05-03-2018"></a>
