		function measureHeight(element)
		{
			var e = document.body.appendChild(element);
			e.style.display = "block";
			e.style.visibility = "hidden";
			e.style.position = "absolute";
			
			var result = e.clientHeight;
			document.body.removeChild(e);
			
			return result;
		}
		
